fn take(arr: Vec<f32>, indices: Vec<usize>) -> Vec<f32> {
    // Pre-allocate the result vector to the exact length of indices
    let mut result = Vec::with_capacity(indices.len());
    
    // For each index, push the corresponding element from `arr`
    for idx in indices {
        // We can safely index into `arr` because the problem guarantees
        // 0 <= idx < arr.len()
        result.push(arr[idx]);
    }
    
    result
}

